import React, { memo, useState } from 'react';
import { X, Check, Star, Video } from 'lucide-react';

const CallFeedbackModal = memo(({ consultant, seconds, onClose }) => {
  const [rating, setRating] = useState(0);

  const handleSubmit = () => {
    onClose();
  };

  const formattedDate = 'Apr 27, 2026, 12:51 PM';

  return (
    <div className='relative bg-[#333333] w-full max-w-md rounded-2xl shadow-2xl overflow-hidden border-t-4 border-green-500 animate-modal-panel'>
      {/* Close Button */}
      <button
        onClick={onClose}
        className='absolute top-4 right-4 text-gray-400 hover:text-white transition-colors'
      >
        <X size={20} />
      </button>

      <div className='p-8 flex flex-col items-center'>
        {/* Success Icon */}
        <div className='w-12 h-12 bg-green-500/20 rounded-full flex items-center justify-center mb-4'>
          <div className='w-8 h-8 bg-green-500 rounded-full flex items-center justify-center text-white'>
            <Check size={20} strokeWidth={4} />
          </div>
        </div>

        <h2 className='text-white font-bold text-2xl mb-8'>
          Consultation Completed
        </h2>

        {/* Consultant Summary Mini-Card */}
        <div className='w-full bg-white/10 rounded-xl p-4 flex items-center gap-4 mb-6 border border-white/5'>
          <img
            src={consultant.image}
            alt=''
            className='w-12 h-12 rounded-full object-cover border border-white/20'
          />
          <div className='flex flex-col'>
            <p className='text-white text-lg font-bold'>{consultant.name}</p>
            <div className='flex items-center gap-1 text-gray-300 text-base'>
              <Video size={14} />
              <span>Video Call</span>
            </div>
          </div>
        </div>

        {/* Stats Grid */}
        <div className='grid grid-cols-3 gap-3 w-full mb-6'>
          {[
            { label: 'Duration', val: `${Math.ceil(seconds / 60)} min` },
            { label: 'Credits Used', val: '25' },
            { label: 'Remaining', val: '175' },
          ].map((s, i) => (
            <div
              key={i}
              className='bg-white/10 rounded-xl py-3 px-1 text-center border border-white/5'
            >
              <p className='text-base text-gray-400 mb-1 uppercase font-medium'>
                {s.label}
              </p>
              <p className='text-white font-bold text-lg'>{s.val}</p>
            </div>
          ))}
        </div>

        {/* Date and Rating Section */}
        <p className='text-base text-gray-400 mb-6 font-medium'>
          {formattedDate}
        </p>

        <p className='text-white text-lg font-bold mb-4'>
          Rate your experience
        </p>

        <div className='flex justify-center gap-2 mb-4'>
          {[...Array(5)].map((_, i) => (
            <button
              key={i}
              onClick={() => setRating(i + 1)}
              className='transition-transform active:scale-90'
            >
              <Star
                size={28}
                fill={i < rating ? '#FFFFFF' : 'none'}
                className={
                  i < rating ? 'text-white' : 'text-white/30 hover:text-white'
                }
              />
            </button>
          ))}
        </div>

        {/* Review Input */}
        <div className='w-full text-left mb-2'>
          <label className='text-white text-lg font-bold block'>Review</label>
        </div>
        <textarea
          placeholder='Write here...'
          className='w-full bg-[#444444] border border-white/10 rounded-xl p-4 text-base text-white placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-green-500/30 h-32 mb-2 resize-none transition-all'
        />
      </div>
    </div>
  );
});

CallFeedbackModal.displayName = 'CallFeedbackModal';

export default CallFeedbackModal;
