import React, { memo, useState, useEffect } from 'react';
import { PhoneOff, Mic, Volume2 } from 'lucide-react';
import CallFeedbackModal from './CallFeedbackModal';
import { useJoinCallMutation, useEndCallMutation, useGetCallByIdQuery } from '../../../features/api/callApi';

const AudioCallModal = memo(({ isOpen, onClose, consultant }) => {
  const [seconds, setSeconds] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [showFeedback, setShowFeedback] = useState(false);
  const [currentBilling, setCurrentBilling] = useState(0);
  const [callId, setCallId] = useState(null);

  const [joinCall] = useJoinCallMutation();
  const [endCall] = useEndCallMutation();

  // Poll for call status every 3 seconds when call is active
  const { data: callData, refetch: refetchCall } = useGetCallByIdQuery(callId, {
    skip: !callId || showFeedback,
    pollingInterval: 3000,
  });

  useEffect(() => {
    let interval;
    if (isOpen && !showFeedback && callId) {
      interval = setInterval(() => {
        setSeconds((prev) => prev + 1);
        setCurrentBilling((prev) => prev + (consultant.price / 60)); // Calculate per second
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isOpen, showFeedback, callId, consultant.price]);

  // Initialize call when modal opens
  useEffect(() => {
    const initializeCall = async () => {
      if (isOpen && !callId && consultant) {
        try {
          // First, check if there's an existing pending call or initiate new one
          const initiateResponse = await fetch('/api/calls/initiate', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${localStorage.getItem('token')}`
            },
            body: JSON.stringify({
              consultantId: consultant.userId || consultant.id,
              callType: 'AUDIO'
            })
          });

          const result = await initiateResponse.json();

          if (result.success && result.data.call.id) {
            setCallId(result.data.call.id);

            // Join the call after initiation
            const joinResult = await joinCall(result.data.call.id).unwrap();

            // Initialize Twilio or WebRTC here if needed
            if (joinResult.token) {
              // Initialize your audio call with Twilio token
              console.log('Audio call initialized with token:', joinResult.token);
            }
          }
        } catch (error) {
          console.error('Failed to initialize call:', error);
          onClose();
        }
      }
    };

    initializeCall();
  }, [isOpen, callId, consultant, joinCall, onClose]);

  // Cleanup when modal closes
  useEffect(() => {
    return () => {
      if (callId && !showFeedback) {
        endCall(callId).catch(console.error);
      }
    };
  }, [callId, endCall, showFeedback]);

  const formatTime = (totalSeconds) => {
    const mins = Math.floor(totalSeconds / 60);
    const secs = totalSeconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleEndCall = async () => {
    try {
      if (callId) {
        const result = await endCall(callId).unwrap();
        console.log('Call ended:', result);
      }
      setShowFeedback(true);
    } catch (error) {
      console.error('Failed to end call:', error);
      setShowFeedback(true);
    }
  };

  const closeAll = () => {
    setSeconds(0);
    setCurrentBilling(0);
    setShowFeedback(false);
    setCallId(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className='fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[9999] p-4 animate-modal-overlay' onClick={(e) => e.stopPropagation()}>
      {!showFeedback ? (
        /* Audio Call UI - Match image_196580.png */
        <div className='relative bg-[#2D2D2D] w-full max-w-md rounded-lg p-4 flex flex-col items-center border border-white/5 animate-modal-panel'>
          <div className='relative bg-[#2D2D2D] w-full max-w-md rounded-lg p-4 flex flex-col items-center border border-white/5 animate-modal-panel' onClick={(e) => e.stopPropagation()}>
            {/* Initial/Avatar Circle */}
            <div className='w-16 h-16 rounded-full bg-[#D1C4E9] flex items-center justify-center mb-4 text-[#5E35B1] text-2xl font-bold'>
              {consultant.name.charAt(0)}
            </div>

            <h2 className='text-white font-bold text-xl mb-1'>
              {consultant.name}
            </h2>
            <p className='text-[#EAB308] text-base font-semibold mb-6 uppercase tracking-wider'>
              Consultation In Progress
            </p>

            <div className='text-4xl font-bold text-white mb-10 font-mono'>
              {formatTime(seconds)}
            </div>

            {/* Billing Pill */}
            <div className='bg-white/10 backdrop-blur-md px-6 py-3 rounded-xl mb-10 text-center border border-white/5'>
              <p className='text-base text-gray-400 mb-1 uppercase tracking-tighter'>
                Current Billing
              </p>
              <p className='text-white font-bold text-xl'>
                €{currentBilling.toFixed(2)}
              </p>
            </div>

            {/* Controls */}
            <div className='flex items-center gap-4'>
              <button
                onClick={() => setIsMuted(!isMuted)}
                className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isMuted ? 'bg-red-500/20 text-red-500' : 'bg-white/10 text-gray-300'}`}
              >
                <Mic size={18} />
              </button>
              <button
                onClick={handleEndCall}
                className='w-12 h-12 bg-red-600 hover:bg-red-700 text-white rounded-full flex items-center justify-center shadow-lg transition-transform active:scale-90'
              >
                <PhoneOff size={20} fill='currentColor' />
              </button>
              <button className='w-10 h-10 rounded-full bg-white/10 text-gray-300 flex items-center justify-center'>
                <Volume2 size={18} />
              </button>
            </div>
          </div>
        </div>
      ) : (
        /* Feedback Modal - Separate Component */
        <CallFeedbackModal
          consultant={consultant}
          seconds={seconds}
          callId={callId}
          onClose={closeAll}
        />
      )}
    </div>
  );
});

AudioCallModal.displayName = 'AudioCallModal';

export default AudioCallModal;